CREATE TABLE "app_settings" ("id" INTEGER NOT NULL DEFAULT 1, "opening_date" TEXT NOT NULL, "weekly_cap" INTEGER NOT NULL, "buffer" INTEGER NOT NULL, "total_card_color" INTEGER NULL, "total_card_finish" TEXT NOT NULL DEFAULT 'matte', "user_name" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "accounts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "kind" TEXT NOT NULL, "name" TEXT NOT NULL, "nickname" TEXT NULL, "opening_balance" INTEGER NOT NULL DEFAULT 0, "color" INTEGER NOT NULL, "ink_color" INTEGER NULL, "finish" TEXT NOT NULL DEFAULT 'matte', "sort_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "transfers" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "occurred_on" TEXT NOT NULL, "from_account_id" INTEGER NOT NULL REFERENCES accounts (id), "to_account_id" INTEGER NOT NULL REFERENCES accounts (id), "amount" INTEGER NOT NULL CHECK("amount" > 0), "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), CHECK (from_account_id <> to_account_id));
CREATE TABLE "categories" ("key" TEXT NOT NULL, "label" TEXT NOT NULL, "kind" TEXT NOT NULL, "tint" TEXT NOT NULL, "is_fixed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_fixed" IN (0, 1)), "monthly_budget" INTEGER NULL, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("key"));
CREATE TABLE "recurring_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "amount" INTEGER NOT NULL CHECK("amount" > 0), "category_key" TEXT NOT NULL REFERENCES categories ("key"), "next_due" TEXT NOT NULL, "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0, 1)), "is_estimate" INTEGER NOT NULL DEFAULT 0 CHECK ("is_estimate" IN (0, 1)), "window_days" INTEGER NOT NULL DEFAULT 0 CHECK("window_days" BETWEEN 0 AND 27), "account_id" INTEGER NOT NULL REFERENCES accounts (id));
CREATE TABLE "planned_events" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "amount" INTEGER NOT NULL CHECK("amount" > 0), "category_key" TEXT NOT NULL REFERENCES categories ("key"), "due_on" TEXT NOT NULL, "done" INTEGER NOT NULL DEFAULT 0 CHECK ("done" IN (0, 1)), "count_in_projection" INTEGER NOT NULL DEFAULT 1 CHECK ("count_in_projection" IN (0, 1)), "repeats_yearly" INTEGER NOT NULL DEFAULT 0 CHECK ("repeats_yearly" IN (0, 1)));
CREATE TABLE "entries" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "occurred_on" TEXT NOT NULL, "kind" TEXT NOT NULL, "amount" INTEGER NOT NULL CHECK("amount" > 0), "category_key" TEXT NOT NULL REFERENCES categories ("key"), "account_id" INTEGER NOT NULL REFERENCES accounts (id), "label" TEXT NULL, "note" TEXT NULL, "receipt" TEXT NULL, "recurring_item_id" INTEGER NULL REFERENCES recurring_items (id), "planned_event_id" INTEGER NULL REFERENCES planned_events (id), "planned_event_on" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "weekly_rules" ("weekday" INTEGER NOT NULL CHECK("weekday" BETWEEN 1 AND 7), "label" TEXT NOT NULL, "day_type" TEXT NOT NULL, "planned_spend" INTEGER NOT NULL DEFAULT 0, "is_fasting_day" INTEGER NOT NULL DEFAULT 0 CHECK ("is_fasting_day" IN (0, 1)), PRIMARY KEY ("weekday"));
CREATE TABLE "goals" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "price" INTEGER NOT NULL CHECK("price" > 0), "target_date" TEXT NOT NULL, "priority" INTEGER NOT NULL DEFAULT 1, "listing_url" TEXT NULL, "status" TEXT NOT NULL DEFAULT 'active', "achieved_on" TEXT NULL);
CREATE TABLE "favourites" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "label" TEXT NOT NULL, "category_key" TEXT NOT NULL REFERENCES categories ("key"), "amount" INTEGER NOT NULL CHECK("amount" > 0), "sort_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "coach_settings" ("id" INTEGER NOT NULL DEFAULT 1, "face" TEXT NOT NULL DEFAULT 'bajety', "personality" TEXT NOT NULL DEFAULT 'friendly', "remember" INTEGER NOT NULL DEFAULT 1 CHECK ("remember" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "coach_threads" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "title" TEXT NOT NULL, "pinned" INTEGER NOT NULL DEFAULT 0 CHECK ("pinned" IN (0, 1)), "face" TEXT NOT NULL, "personality" TEXT NOT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "coach_messages" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "thread_id" INTEGER NOT NULL REFERENCES coach_threads (id) ON DELETE CASCADE, "sent_at" INTEGER NOT NULL, "from_user" INTEGER NOT NULL CHECK ("from_user" IN (0, 1)), "body" TEXT NOT NULL, "face" TEXT NULL, "looked" TEXT NOT NULL DEFAULT '', "cards" TEXT NOT NULL DEFAULT '', "note" INTEGER NOT NULL DEFAULT 0 CHECK ("note" IN (0, 1)));
CREATE TABLE "checkins" ("checked_on" TEXT NOT NULL, "balance" INTEGER NOT NULL, "matched" INTEGER NOT NULL CHECK ("matched" IN (0, 1)), "untracked" INTEGER NOT NULL DEFAULT 0, "starting_adjustment" INTEGER NOT NULL DEFAULT 0, "allowance_spent" INTEGER NOT NULL, "left_after_buying" INTEGER NULL, "next_target" INTEGER NOT NULL, PRIMARY KEY ("checked_on"));
